Resta da definire la funzione $f$ dei \emph{suffix link}. Essa è definita nel modo seguente: se
\[
  x = a\,y, \qquad a \in \S,\ y \in \S^{*},
\]
allora
\[
  f(\bar{x}) \;=\; \bar{y},
\]
cioè il suffix link porta dallo stato associato alla stringa $x$ allo stato associato alla stringa che si ottiene da $x$ cancellandone il primo carattere. Si completa la definizione ponendo $f(\mathrm{root}) = \bot$.

\begin{osservazione}
La funzione $f$ mi consente di costruire un cammino che visita \emph{tutti} i suffissi di $T$. Partendo dallo stato $\bar{x}$ associato al suffisso più lungo, $x = t_1 t_2 \cdots t_n = T$, e applicando ripetutamente $f$ si ottiene
\[
  \overline{t_1\cdots t_n}
  \;\xrightarrow{\ f\ }\; \overline{t_2\cdots t_n}
  \;\xrightarrow{\ f\ }\; \overline{t_3\cdots t_n}
  \;\xrightarrow{\ f\ }\; \cdots
  \;\xrightarrow{\ f\ }\; \overline{t_n}
  \;\xrightarrow{\ f\ }\; \mathrm{root}
  \;\xrightarrow{\ f\ }\; \bot .
\]
Questo cammino prende il nome di \textbf{boundary path}.
\end{osservazione}

\begin{figure}[H]
\centering
\input{tikz/boundary-path.tikz}
\caption{Il \emph{boundary path} di $\STrie(T)$: applicando ripetutamente il suffix link $f$ a partire dallo stato $\bar{x}$ del suffisso più lungo $x = t_1\cdots t_n$ si incontrano, nell'ordine, gli stati di tutti i suffissi di $T$.}
\end{figure}

\paragraph{Intuizione.}
Passerò da $\STrie(\pre{T}{i-1})$ a $\STrie(\pre{T}{i})$ visitando il boundary path e aggiungendo una transizione (quando necessario) ad ogni passo. Il motivo per cui questo basta è che l'insieme degli stati cresce solo lungo i suffissi:
\[
  Q\bigl(\pre{T}{i}\bigr) \;=\; Q\bigl(\pre{T}{i-1}\bigr) \;\cup\;
  \set{\, \overline{t_j\cdots t_i} \;:\; 1 \le j \le i \,} .
\]
Infatti ogni sottostringa di $\pre{T}{i}$ che non sia già sottostringa di $\pre{T}{i-1}$ deve terminare con il carattere $t_i$, cioè è un suffisso di $\pre{T}{i}$; e i suffissi di $\pre{T}{i}$ sono esattamente gli stati del boundary path di $\STrie(\pre{T}{i-1})$ estesi con $t_i$.

Per costruire $\STrie(T)$ eseguirò dunque $\abs{T}$ volte l'operazione
\[
  \STrie\bigl(\pre{T}{i-1}\bigr) \;\longrightarrow\; \STrie\bigl(\pre{T}{i}\bigr).
\]
Ognuna ha costo $i$, per $i \in \set{1,\dots,n}$: il boundary path di $\STrie(\pre{T}{i-1})$ ha infatti $i$ stati (i suffissi di $\pre{T}{i-1}$, compresa $\e$, cioè la radice) più lo stato $\bot$. Sommando,
\[
  \sum_{i=1}^{n} \Oh(i) \;=\; \Oh\bigl(\abs{T}^{2}\bigr),
\]
cioè un \textbf{algoritmo quadratico}.

Ed è \emph{ottimo}: la sola dimensione di $\STrie(T)$ può essere $\Th(\abs{T}^{2})$ — si pensi a $T = a^{n}b^{n}$ — quindi nessun algoritmo che costruisca esplicitamente il suffix trie può costare meno.

\paragraph{Algoritmo 1.}

\begin{algorithm}[H]
\caption{Costruzione di $\STrie(T)$ per $T = t_1 t_2 \cdots t_n$}
\begin{algorithmic}[1]
  \State crea gli stati $\mathrm{root}$ e $\bot$
  \State $g(\bot, a) \gets \mathrm{root}$ per ogni $a \in \S$;\quad $f(\mathrm{root}) \gets \bot$
  \State $\mathit{top} \gets \mathrm{root}$
  \For{$i \gets 1$ \textbf{to} $n$}
    \State $r \gets \mathit{top}$
    \While{$g(r, t_i)$ è indefinita}
      \State crea un nuovo stato $r'$ e poni $g(r, t_i) \gets r'$
      \If{$r \neq \mathit{top}$}
        \State $f(\mathit{oldr}') \gets r'$
        \Comment{alla prima iterazione $\mathit{oldr}'$ non è ancora definito}
      \EndIf
      \State $\mathit{oldr}' \gets r'$
      \State $r \gets f(r)$
    \EndWhile
    \State $f(\mathit{oldr}') \gets g(r, t_i)$
    \State $\mathit{top} \gets g(\mathit{top}, t_i)$
  \EndFor
\end{algorithmic}
\end{algorithm}

\begin{osservazione}
Il ciclo \textbf{while} termina sempre: risalendo il boundary path con $r \gets f(r)$ si arriva al più a $\bot$, dove $g(\bot, t_i) = \mathrm{root}$ è definita per ogni carattere. La variabile $\mathit{top}$ mantiene l'invariante $\mathit{top} = \overline{t_1\cdots t_i}$ alla fine del passo $i$-esimo, cioè è sempre il capo del boundary path corrente.
\end{osservazione}
